select 'role' as k, string_agg(e.enumlabel, ' | ' order by e.enumsortorder) as v from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typname='user_role'
union all select 'order_status', string_agg(e.enumlabel, ' | ' order by e.enumsortorder) from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typname='order_status'
union all select 'delivery_status', string_agg(e.enumlabel, ' | ' order by e.enumsortorder) from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typname='delivery_status'
union all select 'stock_movement_type', string_agg(e.enumlabel, ' | ' order by e.enumsortorder) from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typname='stock_movement_type'
union all select 'stock_movement_source', string_agg(e.enumlabel, ' | ' order by e.enumsortorder) from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typname='stock_movement_source'
union all select 'production_qc_status', string_agg(e.enumlabel, ' | ' order by e.enumsortorder) from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typname='production_qc_status'
union all select 'purchase_order_status', string_agg(e.enumlabel, ' | ' order by e.enumsortorder) from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typname='purchase_order_status'
union all select 'dealer_status', string_agg(e.enumlabel, ' | ' order by e.enumsortorder) from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typname='dealer_status'
union all select 'payment_mode', string_agg(e.enumlabel, ' | ' order by e.enumsortorder) from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typname='payment_mode'
union all select 'designations', string_agg(name, ' | ' order by sort_order) from public.designations;
